mapper.select:
SELECT COUNT(*) CNT
  FROM RECIPE_VIEW_LOG
 WHERE RECIPE_ID = #{recipeId}
   AND USER_ID = #{userId}
   AND VIEW_DAY = CURDATE()

mapper.insert:
INSERT INTO RECIPE_VIEW_LOG
      ( RECIPE_ID
      , USER_ID
      , VIEWED_AT
      , VIEW_DAY
      )
VALUES( #{recipeId}
      , #{userId}
      , NOW()
      , CURDATE()
      )

mapper.update:
UPDATE RECIPE_MASTER
   SET VIEW_COUNT = VIEW_COUNT + 1
 WHERE RECIPE_ID = #{recipeId}

UPDATE RECIPE_MASTER
SET CLAIMED_POINT = #{claimedPoint}
WHERE RECIPE_ID = #{recipeId}
